package app.nlc.archiveqa;
import android.app.Instrumentation; import android.os.Bundle; import android.content.Context; import android.net.Uri; import android.provider.DocumentsContract; import org.json.*; import java.io.*; import java.lang.reflect.*; import java.util.*; import java.util.zip.*; import java.security.MessageDigest;
public class ArchiveQA extends Instrumentation {
 Bundle args; Object archive; Class<?> cls, callbackClass; Context target; JSONArray passed=new JSONArray(); File work; String selected; String savedArchive;
 public void onCreate(Bundle b){super.onCreate(b);args=b;start();}
 Object call(String name,Object...values)throws Exception {for(Method m:cls.getMethods())if(m.getName().equals(name)&&m.getParameterCount()==values.length)try{return m.invoke(archive,values);}catch(InvocationTargetException e){Throwable t=e.getCause();if(t instanceof Exception)throw(Exception)t;throw e;}throw new Exception("Missing method "+name);}
 void ok(boolean result,String message)throws Exception {if(!result)throw new Exception(message);}
 Object callback(boolean cancel,String job)throws Exception {return Proxy.newProxyInstance(callbackClass.getClassLoader(),new Class<?>[]{callbackClass},(proxy,method,a)->{if(method.getName().equals("invoke")&&cancel&&((Number)a[0]).longValue()>2*1024*1024)call("cancel",job);return Class.forName("kotlin.Unit",true,target.getClassLoader()).getField("INSTANCE").get(null);});}
 String uri(File file){return Uri.fromFile(file).toString();}
 String sha(InputStream in)throws Exception {MessageDigest d=MessageDigest.getInstance("SHA-256");try(InputStream input=in){byte[]b=new byte[128*1024];int n;while((n=input.read(b))>=0)d.update(b,0,n);}StringBuilder s=new StringBuilder();for(byte b:d.digest())s.append(String.format("%02x",b&255));return s.toString();}
 JSONObject plan(File source,String destination,String job)throws Exception {
  File metadata=new File(work,"native-meta.json");try(OutputStream out=new FileOutputStream(metadata)){out.write("{\"format\":\"native-test\"}".getBytes("UTF-8"));}
  return new JSONObject().put("job",job).put("destination",destination).put("metadataUri",uri(metadata)).put("files",new JSONArray().put(new JSONObject().put("path","media/series/Prueba:100%/episodio.mp4").put("uri",uri(source)).put("bytes",source.length())));
 }
 Uri asDocument(Uri value){return DocumentsContract.isTreeUri(value)&&!value.getPath().contains("/document/")?DocumentsContract.buildDocumentUriUsingTree(value,DocumentsContract.getTreeDocumentId(value)):value;}

 public void onStart(){Bundle result=new Bundle();int code=0;try{
  target=getTargetContext();cls=Class.forName("app.nlc.lanbridge.ServiceArchive",true,target.getClassLoader());archive=cls.getField("INSTANCE").get(null);callbackClass=Class.forName("kotlin.jvm.functions.Function2",true,target.getClassLoader());work=new File(target.getCacheDir(),"archive-native-qa");work.mkdirs();
  File source=new File(work,"large.bin");long size=Long.parseLong(args.getString("size","335544320"));byte[]block=new byte[128*1024];new Random(7831).nextBytes(block);try(OutputStream out=new BufferedOutputStream(new FileOutputStream(source))){for(long n=0;n<size;n+=block.length)out.write(block);}String expected=sha(new FileInputStream(source));
  String destination=args.getString("destination");if("auto".equals(destination)){destination=null;for(android.content.UriPermission permission:target.getContentResolver().getPersistedUriPermissions())if(Uri.decode(permission.getUri().toString()).contains("NLC-Service-QA/Health")){destination=permission.getUri().toString();break;}ok(destination!=null,"Choose the NLC-Service-QA/Health folder in the local onboarding first");}
  File zip=new File(work,"large.zip");String zipUri=uri(zip);if(destination!=null&&destination.startsWith("content:")){Uri file=DocumentsContract.createDocument(target.getContentResolver(),asDocument(Uri.parse(destination)),"application/zip","NLC-QA-"+UUID.randomUUID()+".zip");savedArchive=file.toString();zipUri=savedArchive;}
  String job=UUID.randomUUID().toString();JSONObject exported=new JSONObject((String)call("export",target,plan(source,zipUri,job).toString(),callback(false,job)));ok(exported.getLong("bytes")>size,"ZIP must contain actual media bytes");passed.put(zipUri.startsWith("content:")?"SAF-stream-export":"private-stream-export");
  job=UUID.randomUUID().toString();JSONObject stage=new JSONObject((String)call("prepare",target,zipUri,job,callback(false,job)));String media="media/series/Prueba:100%/episodio.mp4";String extracted=stage.getJSONObject("files").getJSONObject(media).getString("uri");ok(sha(target.getContentResolver().openInputStream(Uri.parse(extracted))).equals(expected),"staged media checksum");passed.put(zipUri.startsWith("content:")?"SAF-stream-import-sha256":"private-stream-import-sha256");
  if(destination==null){File directory=new File(work,"destination");directory.mkdir();destination=uri(directory);}
  job=UUID.randomUUID().toString();JSONObject committed=new JSONObject((String)call("commit",target,stage.getString("id"),destination,job,callback(false,job)));selected=committed.getString("root");String restored=committed.getJSONObject("files").getString(media);ok(sha(target.getContentResolver().openInputStream(Uri.parse(restored))).equals(expected),"restored media checksum");passed.put(destination.startsWith("content:")?"SAF-destination-stream-sha256":"private-destination-stream-sha256");
  JSONArray listing=new JSONArray((String)call("list",target,selected));ok(listing.length()==1&&listing.getJSONObject(0).getLong("bytes")==size,"recursive directory listing");ok(listing.getJSONObject(0).getString("path").equals(committed.getJSONObject("paths").getString(media)),"actual normalized filename mapping"); ok(restored.endsWith(".mp4"),"media extension survives SAF MIME normalization"); passed.put("normalized-filenames-and-mime-extension");
  call("discard",target,stage.getString("id"));ok(!new File(target.getCacheDir(),"service-archives/"+stage.getString("id")).exists(),"discard stage");
  job=UUID.randomUUID().toString();boolean rejected=false;try{call("prepare",target,zipUri,job,callback(true,job));}catch(Exception e){rejected=e.getMessage().contains("cancelled");}ok(rejected,"cancel import staging");passed.put("cancel-import-staging");
  job=UUID.randomUUID().toString();File cancelled=new File(work,"cancelled.zip");rejected=false;try{call("export",target,plan(source,uri(cancelled),job).toString(),callback(true,job));}catch(Exception e){rejected=e.getMessage().contains("cancelled");}ok(rejected&&!cancelled.exists(),"cancel removes incomplete output");passed.put("cancel-export-removes-partial-copy");
  File evil=new File(work,"evil.zip");try(ZipOutputStream out=new ZipOutputStream(new FileOutputStream(evil))){out.putNextEntry(new ZipEntry("media/../escape"));out.write(1);out.closeEntry();}job=UUID.randomUUID().toString();rejected=false;try{call("prepare",target,uri(evil),job,callback(false,job));}catch(Exception e){rejected=true;}ok(rejected&&!new File(target.getCacheDir(),"escape").exists(),"path traversal");passed.put("reject-traversal-before-live-writes");
  if(!zipUri.startsWith("file:"))try(InputStream input=target.getContentResolver().openInputStream(Uri.parse(zipUri));OutputStream out=new FileOutputStream(zip)){byte[]buffer=new byte[128*1024];int n;while((n=input.read(buffer))>=0)out.write(buffer,0,n);}
  try(RandomAccessFile f=new RandomAccessFile(zip,"rw")){f.seek(5000);int original=f.read();f.seek(5000);f.write(original^1);}job=UUID.randomUUID().toString();rejected=false;try{call("prepare",target,uri(zip),job,callback(false,job));}catch(Exception e){rejected=true;}ok(rejected,"corrupted archive");passed.put("reject-damaged-media");
  result.putString("report",new JSONObject().put("passed",passed).put("mediaBytes",size).put("maxJavaHeap",Runtime.getRuntime().maxMemory()).put("sha256",expected).put("destination",selected).toString());
 }catch(Throwable e){result.putString("error",e.toString());result.putString("passed",passed.toString());code=1;}finally{if(work!=null)delete(work);if(savedArchive!=null)try{DocumentsContract.deleteDocument(target.getContentResolver(),Uri.parse(savedArchive));}catch(Exception ignored){}if(selected!=null)try{Uri u=Uri.parse(selected);if(u.getScheme().equals("content"))DocumentsContract.deleteDocument(target.getContentResolver(),u);else delete(new File(u.getPath()));}catch(Exception ignored){}}finish(code,result);}
 void delete(File f){if(f.isDirectory()){File[]children=f.listFiles();if(children!=null)for(File c:children)delete(c);}f.delete();}
}
